$top = Get-ChildItem -Path 'C:\' -Directory -Force -ErrorAction SilentlyContinue | Where-Object { $_.Name -ne 'Windows' -and $_.Name -ne '$Recycle.Bin' } | ForEach-Object { $size = (Get-ChildItem -Path $_.FullName -Recurse -Force -File -ErrorAction SilentlyContinue | Measure-Object -Property Length -Sum -ErrorAction SilentlyContinue).Sum; [PSCustomObject]@{Path=$_.FullName; SizeBytes=$size} } | Sort-Object SizeBytes -Descending | Select-Object -First 8; foreach ($d in $top) { Write-Output ''; Write-Output ('=== ' + $d.Path + ' (' + [math]::Round($d.SizeBytes/1GB,2) + ' GB) ==='); Get-ChildItem -Path $d.Path -Directory -Force -ErrorAction SilentlyContinue | ForEach-Object { $s = (Get-ChildItem -Path $_.FullName -Recurse -Force -File -ErrorAction SilentlyContinue | Measure-Object -Property Length -Sum -ErrorAction SilentlyContinue).Sum; [PSCustomObject]@{SubDir=$_.FullName; SizeGB=[math]::Round($s/1GB,2)} } | Sort-Object SizeGB -Descending | Select-Object -First 15 | Format-Table -AutoSize | Out-String | Write-Output }
